# -*- coding: utf-8 -*-
# أخطاء تربوية إضافية: t, d, sci, steps, say
M = []
def m(t, d, sci, steps, say=None): M.append(dict(t=t, d=d, sci=sci, steps=steps, say=say or []))
m('الحماية الزائدة والقيام بكل شيء عن الطفل', 'خوف الوالدين يمنع الطفل من التجربة والخطأ.', 'الطفل يبني ثقته ومهاراته من التجارب التي ينجح فيها بنفسه، والحماية الزائدة ترتبط بالقلق وضعف الاعتماد على النفس.', ['اسمح بالمخاطر الصغيرة الآمنة: يتسلق، يطبخ مع إشرافك.', 'لا تحل مشكلاته مع أصدقائه بدلاً منه؛ علّمه كيف يحلها.', 'مهام منزلية تناسب عمره.', 'ذكّر نفسك: هدف التربية أن يستغني عنك يوماً.'], [['اتركه، أنا أسويه عنك', 'جرّب، وإذا احتجت أنا قريب']])
m('التهديد بما لا يُنفَّذ', 'تهديدات كثيرة لا تُطبّق: «سأتركك هنا»، «لن تخرج أبداً».', 'التهديد غير المنفّذ يعلّم الطفل أن كلام والديه لا قيمة له، والتهديد المخيف يزرع القلق.', ['لا تذكر عاقبة إلا إذا كنت ستنفذها فعلاً.', 'اجعل العاقبة قصيرة ومعقولة ومرتبطة بالخطأ.', 'نفّذ بهدوء وبلا محاضرة.'], [['سأتركك في السوق!', 'إذا ركضت مرة ثانية نرجع للسيارة']])
m('العقاب بالحرمان من الطعام أو النوم', 'حرمان الطفل من وجبة أو إرساله للنوم جائعاً.', 'الحاجات الأساسية ليست ورقة ضغط؛ ربطها بالعقاب يضر بالصحة وبعلاقة الطفل بالطعام والنوم.', ['استخدم عواقب منطقية بدلاً منها.', 'لا تجعل الحلوى مكافأة ولا الطعام عقاباً.'])
m('الانشغال الدائم بالجوال أمام الأطفال', 'الوالد حاضر بجسده غائب بعقله.', 'تشير دراسات إلى أن انشغال الوالدين بالأجهزة أثناء التفاعل مع الطفل يقلل التواصل ويرتبط بزيادة سلوكيات طلب الانتباه.', ['أوقات بلا أجهزة: الوجبات، وأول ساعة بعد العودة، وقبل النوم.', 'إن احتجت الجوال اشرح له: «أرد على رسالة عمل دقيقتين».', 'نشاط أسبوعي مشترك بلا شاشات.'], [['(تهزّ رأسك وأنت تقرأ الجوال)', 'لحظة أضع الجوال… الآن احكِ لي']])
m('عدم الاتفاق بين الأب والأم أمام الأطفال', 'الأب يسمح والأم تمنع، أو العكس.', 'التناقض يربك الطفل ويعلمه أن يستغل الطرف الأسهل، ويضعف سلطة الوالدين معاً.', ['اتفقا على القواعد الأساسية مسبقاً.', 'الخلاف يناقش بعيداً عن الأطفال.', 'لا تنقض قرار الآخر أمامهم.', 'قل: «سأتكلم مع أمك/أبيك ونرد عليك».'])
m('الاستهزاء بمشاعر الطفل', 'السخرية من خوفه أو بكائه أو اهتماماته.', 'إنكار مشاعر الطفل يعلمه أن يخفيها، فلا يأتي إليك حين يكون في خطر.', ['اعترف بالشعور قبل أي توجيه.', 'لا تحكِ مواقفه المحرجة أمام الآخرين.', 'احترم اهتماماته ولو بدت صغيرة.'], [['تخاف من هذا؟ هههه', 'أفهم أنك خايف، تعال نشوفه معاً']])
m('التدليل المفرط وتلبية كل الطلبات', 'إعطاء الطفل كل ما يريد فوراً.', 'الطفل الذي لا يتعلم الانتظار والحرمان المؤقت يصعب عليه ضبط نفسه لاحقاً، وتجارب «تأجيل الإشباع» ترتبط مهارتها بنجاح أفضل.', ['دعه ينتظر ويدّخر لما يريد.', 'الهدايا في المناسبات لا يومياً.', 'المحبة بالوقت والاهتمام لا بالأشياء.'])
m('كثرة الأوامر والتعليمات', 'سيل من الأوامر طوال اليوم: «افعل… لا تفعل».', 'مع كثرة الأوامر يتوقف الطفل عن الاستماع، كما يتجاهل الإنسان الضجيج المستمر.', ['قلّل الأوامر إلى الأهم.', 'أمر واحد واضح في كل مرة.', 'صِغ الأمر إيجابياً: «امشِ» بدل «لا تركض».', 'استخدم الروتين والجداول بدل التكرار.'])
m('الوعظ الطويل بعد كل خطأ', 'محاضرة طويلة كلما أخطأ.', 'الطفل يتوقف عن الاستماع بعد دقيقة أو اثنتين، وكثرة الوعظ تنفّر من الحق نفسه.', ['جملة أو اثنتان تكفي.', 'اسأل: «ما الذي كان يمكن أن تفعله بدلاً من ذلك؟».', 'كان النبي ﷺ يتخوّل أصحابه بالموعظة مخافة السآمة.'])
m('إلقاء اللوم على الطفل في خلافات الكبار', 'إشراكه في مشكلات الزوجين أو العائلة.', 'تحميل الطفل هموم الكبار يسرق طفولته ويشعره بالذنب والقلق.', ['لا تشكُ له من الطرف الآخر.', 'لا تطلب منه أن يختار بينكما.', 'طمئنه أن مشكلات الكبار يحلها الكبار.'])
m('تجاهل السلوك الحسن والانتباه للسيئ فقط', 'لا يسمع الطفل تعليقاً إلا حين يخطئ.', 'الطفل يحتاج إلى الانتباه، فإذا لم يحصل عليه بالسلوك الحسن طلبه بالسيئ.', ['«امسكه وهو يُحسن»: امدح السلوك الحسن فوراً ومحدداً.', 'اجعل نسبة التعليقات الإيجابية أكثر بكثير من السلبية.', 'تجاهل السلوكيات المزعجة البسيطة غير الخطرة.'])
m('عقاب الطفل وأنت غاضب', 'العقوبة في لحظة الغضب.', 'العقاب في الغضب يكون غالباً أشد من الخطأ، ويتذكر الطفل غضبك لا الدرس.', ['أجّل القرار: «سنتكلم بعد أن أهدأ».', 'هدي الغضب: السكوت والوضوء وتغيير الهيئة.', 'لا يقضي القاضي وهو غضبان، فكيف بالوالد مع ولده.'])
m('فرض المستقبل والتخصص على الأبناء', 'اختيار التخصص والمهنة نيابة عنه.', 'الدافعية الداخلية أقوى أسباب النجاح، والإجبار يرتبط بضعف الإنجاز والندم.', ['ساعده في اكتشاف ميوله وقدراته.', 'قدّم المعلومات والخبرة، واترك له القرار في المباح.', 'شاوره: «أنت تعيش هذا المستقبل».'])
m('المقارنة بالآباء: «نحن في زماننا…»', 'رفض الواقع الجديد ومقارنته بالماضي دائماً.', 'الطفل يعيش زماناً مختلفاً، وكثرة المقارنة بالماضي تجعله يشعر أن والديه لا يفهمانه.', ['افهم عالمه قبل أن تحكم عليه.', 'استخدم قصص الماضي للإلهام لا للتوبيخ.', 'فرّق بين الثوابت التي لا تتغير والوسائل التي تتغير بتغير الزمان.'])
m('التفريط في متابعة الأصدقاء والصحبة', 'لا يعرف الوالدان أصدقاء أبنائهم.', 'الأقران من أقوى المؤثرات في سلوك الطفل والمراهق.', ['اعرف أصدقاءه بالاسم وأهلهم.', 'اجعل بيتك مكاناً مرحّباً بأصدقائه.', '«المرء على دين خليله».'])
m('ربط الحب بالدرجات والإنجاز', 'المحبة والرضا مرتبطان بالنجاح فقط.', 'الطفل الذي يشعر أن حب والديه مشروط بالإنجاز يصبح قلقاً ويخاف الفشل.', ['أظهر حبك في الفشل كما في النجاح.', 'افصل بين تقييم العمل وقيمة الطفل.', '«أحبك دائماً، وسنعمل على تحسين الدرجة معاً».'])
m('الضغط لتحفيظ القرآن بالقسوة', 'الضرب والصراخ في حلقات التحفيظ في البيت.', 'ربط القرآن بالخوف والألم قد يورث نفوراً يدوم، بينما يرتبط الحفظ الثابت بالتكرار المحبب.', ['جلسات قصيرة محبّبة.', 'مكافآت وإنجازات مرئية.', 'افهموا المعاني معاً.', 'القدوة: يرى والديه يقرآن.'])
m('إهمال الأب لدوره التربوي', 'ترك التربية كلها للأم بحجة العمل.', 'تشير الأبحاث إلى أن مشاركة الأب في التربية ترتبط بتحصيل أفضل وسلوك أفضل وثقة أعلى لدى الأبناء والبنات.', ['وقت يومي ولو قصير مع كل ابن.', 'نشاط أسبوعي: صلاة الجمعة، رياضة، مشوار.', 'شارك في قرارات التربية والمدرسة.', '«كلكم راعٍ وكلكم مسؤول عن رعيته».'])
m('عدم الاعتذار للطفل عند الخطأ', 'الوالد لا يعترف بخطئه أبداً.', 'اعتذار الوالد يعلم الطفل الاعتذار والتواضع، ويصلح العلاقة بعد الخلاف.', ['اعتذر بوضوح: «آسف أني صرخت».', 'بيّن ما ستفعله المرة القادمة.', 'الاعتذار لا يُسقط هيبتك، بل يزيد احترامك.'])
m('تخويف الطفل بالله وحده', 'ربط الله بالعقاب فقط: «الله يحرقك».', 'البدء بالمحبة والرجاء يورث محبة الله وطاعته، والتخويف وحده قد يورث النفور.', ['عرّفه بنعم الله ورحمته أولاً.', 'ثم علّمه المراقبة برفق.', 'كان النبي ﷺ يبشّر وييسّر: «يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا».'], [['الله يحرقك إذا كذبت', 'الله يحب الصادقين، والصدق يجعل قلبك مرتاحاً']])
